const legacySignup=new URLSearchParams(location.search);if(['trial','purchase'].includes(legacySignup.get('intent'))){const plan=['starter','professional','business'].includes(legacySignup.get('plan'))?legacySignup.get('plan'):'professional';location.replace('https://stoneflowapp.pureknight.co.uk/signup?plan='+plan);}
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#navigation');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});
const tour={dashboard:{src:'/assets/dashboard.webp',title:'See what needs doing.',copy:'Quotes waiting for review, work assigned to each estimator and follow-ups that are due, on one dashboard.',alt:'StoneFlow dashboard with quotation review queues and reporting'},schedule:{src:'/assets/schedule.webp',title:'Works like a spreadsheet.',copy:'Paste rows from Excel, pick standard products and calculate material pricing and mould allowances. Anything missing is flagged for the estimator to check.',alt:'StoneFlow component schedule showing dimensions, quantities, pricing and review warnings'}};
const tabs=[...document.querySelectorAll('[data-tab]')];
function selectTab(button){const item=tour[button.dataset.tab];tabs.forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1});document.querySelector('#tour-copy h3').textContent=item.title;document.querySelector('#tour-copy p').textContent=item.copy;const img=document.querySelector('#tour-image');img.src=item.src;img.alt=item.alt;document.querySelector('#tour-open').dataset.image=item.src;document.querySelector('#tour-panel').setAttribute('aria-labelledby',button.id)}
tabs.forEach((button,index)=>{button.addEventListener('click',()=>selectTab(button));button.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();selectTab(tabs[next]);tabs[next].focus()})});
const dialog=document.querySelector('#image-dialog');document.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>{const img=dialog.querySelector('img');img.src=button.dataset.image;img.alt=button.querySelector('img').alt;dialog.showModal()}));dialog?.querySelector('button').addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const hours=document.querySelector('#hours'),rate=document.querySelector('#rate');function calculate(){const h=Number(hours.value),r=Math.min(1000,Math.max(0,Number(rate.value)||0));document.querySelector('#hours-value').textContent=h+' '+(h===1?'hour':'hours');document.querySelector('#saving').textContent=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(h*r*52/12)}if(hours){hours.addEventListener('input',calculate);rate.addEventListener('input',calculate);calculate()}
const form=document.querySelector('#enquiry-form');
if(form){const params=new URLSearchParams(location.search),plan=document.querySelector('#plan'),intent=document.querySelector('#intent'),names={starter:'Starter',professional:'Professional',business:'Business'},prices={starter:99,professional:199,business:399};if(names[params.get('plan')])plan.value=params.get('plan');if(['demo','trial','purchase','question'].includes(params.get('intent')))intent.value=params.get('intent');function summary(){const box=document.querySelector('#selection-summary');box.hidden=intent.value!=='trial'&&intent.value!=='purchase';box.replaceChildren();if(box.hidden)return;const strong=document.createElement('strong');strong.textContent=(intent.value==='trial'?'14-day trial request':'Plan purchase enquiry')+(names[plan.value]?' · '+names[plan.value]:'');const small=document.createElement('small');small.textContent=intent.value==='trial'?'We’ll arrange your workspace and confirm when your trial begins. No automatic subscription.':'We’ll confirm the proposed price, terms and setup before any payment.';box.append(strong,small)}summary();plan.addEventListener('change',summary);intent.addEventListener('change',summary);form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),kind={demo:'Demonstration request',trial:'14-day trial request',purchase:'Plan purchase enquiry',question:'Product enquiry'}[data.get('intent')],selected=names[plan.value]||'Please help me choose';const body=`Hello Pure Knight,\n\n${kind} for StoneFlow.\n\nName: ${String(data.get('name')).trim()}\nEmail: ${String(data.get('email')).trim()}\nCompany: ${String(data.get('company')).trim()}\nPlan: ${selected}${prices[plan.value]?' (proposed £'+prices[plan.value]+'/month excluding VAT)':''}\n\n${String(data.get('message')||'').trim()}\n\nPlease confirm availability, final pricing, allowances and terms before setup.`;document.querySelector('#prepared-message').value=body;document.querySelector('#email-fallback').hidden=false;document.querySelector('#form-status').textContent='Your email is prepared. Send it from your email app, or use the copy option below. Your enquiry has not been sent by this website.';const mail=document.createElement('a');mail.href='mailto:info@pureknight.co.uk?subject='+encodeURIComponent('StoneFlow — '+kind+' — '+selected)+'&body='+encodeURIComponent(body);mail.click()});document.querySelector('#copy-message').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#prepared-message').value);document.querySelector('#form-status').textContent='Message copied. Paste it into an email to info@pureknight.co.uk.'}catch{document.querySelector('#prepared-message').select();document.querySelector('#form-status').textContent='Select and copy the prepared message, then email it to info@pureknight.co.uk.'}})}
